var rig=UnityEngine.Object.FindObjectOfType<Character.Control.PaddleCharacterVisual>();
float max=0; string worst="";
foreach(float growth in new[]{.65f,1f,1.5f})foreach(float reach in new[]{.75f,1.05f,1.975f})for(int i=0;i<72;i++){
 var q=UnityEngine.Quaternion.Euler(0,0,i*5);
 rig.body.localScale=UnityEngine.Vector3.one*7.5f*growth;
 rig.tool.localScale=UnityEngine.Vector3.one*growth;rig.tool.rotation=q;rig.tool.position=rig.body.position+q*new UnityEngine.Vector3(reach*growth,.074f*growth,0);
 rig.Pose();if(rig.HandError>max){max=rig.HandError;worst=growth+" / "+reach+" / "+i*5;}
}
UnityEngine.Debug.Log("648 poses maxHandError="+max+" worst="+worst);
